{
  "assessments": [
    {
      "proposition_id": "P1",
      "status": "partial",
      "summary_quote": "Eligible students are Tennessee residents entitled to attend public school, excluding those in home schools or certain church-related schools.",
      "rationale": "Covers residency, public-school entitlement, and exclusions, but does not identify the parental association or parent-teacher condition defining the excluded church-related enrollment."
    },
    {
      "proposition_id": "P2",
      "status": "partial",
      "summary_quote": "eligible students who enroll in an approved private school",
      "rationale": "Conveys required enrollment in an approved private school, but omits Tennessee location and the category I, II, or III qualification."
    },
    {
      "proposition_id": "P3",
      "status": "partial",
      "summary_quote": "This bill proposes the creation of the Education Freedom Scholarship Act, a state-funded program administered by the department of education. Starting in the 2025-2026 school year, the program would award up to 20,000 scholarships to eligible students who enroll in an approved private school.",
      "rationale": "Identifies the program, administering department, and start year, but omits the condition that awards depend on appropriations and other available funds."
    },
    {
      "proposition_id": "P4",
      "status": "partial",
      "summary_quote": "Starting in the 2025-2026 school year, the program would award up to 20,000 scholarships to eligible students who enroll in an approved private school. Half of these scholarships are reserved for students who meet specific income thresholds (up to 300% of the free or reduced price lunch level) or meet specific existing eligibility criteria; the other half are available to any eligible student regardless of income.",
      "rationale": "Covers the initial cap, equal division, and income threshold, but omits completed-application receipt order and does not identify the alternative statutory eligibility groups."
    },
    {
      "proposition_id": "P5",
      "status": "partial",
      "summary_quote": "For the 2026-2027 school year and beyond, the bill establishes rules for increasing the number of scholarships if demand is high",
      "rationale": "Conveys demand-based expansion and its starting year, but omits the 75% trigger, discretionary 5,000 maximum increase for the next year, funding conditions, and unchanged-cap rule."
    },
    {
      "proposition_id": "P6",
      "status": "partial",
      "summary_quote": "For the 2026-2027 school year and beyond, the bill establishes rules for increasing the number of scholarships if demand is high and sets a priority order for awarding scholarships when applications exceed availability.",
      "rationale": "Conveys when prioritization applies, but omits all priority tiers and completed-application receipt ordering within the later tiers."
    },
    {
      "proposition_id": "P7",
      "status": "partial",
      "summary_quote": "the program would award up to 20,000 scholarships to eligible students who enroll in an approved private school",
      "rationale": "Conveys private-school enrollment as a scholarship condition, but omits the completed application, compulsory-attendance requirement, prohibition on public-school enrollment during a scholarship year, and expanded parent and public-school definitions."
    },
    {
      "proposition_id": "P8",
      "status": "omitted",
      "summary_quote": "",
      "rationale": "Does not mention authority to award scholarships out of order following an administrative appeal."
    },
    {
      "proposition_id": "P9",
      "status": "full",
      "summary_quote": "This bill proposes the creation of the Education Freedom Scholarship Act, a state-funded program administered by the department of education. Starting in the 2025-2026 school year, the program would award up to 20,000 scholarships to eligible students who enroll in an approved private school. Half of these scholarships are reserved for students who meet specific income thresholds (up to 300% of the free or reduced price lunch level) or meet specific existing eligibility criteria; the other half are available to any eligible student regardless of income. Eligible students are Tennessee residents entitled to attend public school, excluding those in home schools or certain church-related schools. \n\nScholarships equal the base funding amount defined in the Tennessee Investment in Student Achievement (TISA) formula.",
      "rationale": "Identifies state funding and scholarships equal to the TISA base funding amount."
    },
    {
      "proposition_id": "P10",
      "status": "full",
      "summary_quote": "Funds must first cover tuition and fees, with remaining balances available for textbooks, approved tutoring, transportation, technology, certain academic programs, approved postsecondary exams, and educational therapy.",
      "rationale": "Conveys tuition-and-fee payment priority and limits remaining balances to specified educational uses."
    },
    {
      "proposition_id": "P11",
      "status": "partial",
      "summary_quote": "Funds must first cover tuition and fees, with remaining balances available for textbooks",
      "rationale": "Includes textbooks after tuition and fees, but omits curricula, instructional materials, uniforms, and the requirement that the private school require these items."
    },
    {
      "proposition_id": "P12",
      "status": "full",
      "summary_quote": "Funds must first cover tuition and fees, with remaining balances available for textbooks, approved tutoring",
      "rationale": "Conveys that remaining funds can pay for tutoring subject to approval requirements."
    },
    {
      "proposition_id": "P13",
      "status": "partial",
      "summary_quote": "Funds must first cover tuition and fees, with remaining balances available for textbooks, approved tutoring, transportation",
      "rationale": "Includes transportation after tuition and fees, but omits travel to and from the private school and the qualifying fee-for-service provider requirement."
    },
    {
      "proposition_id": "P14",
      "status": "partial",
      "summary_quote": "Funds must first cover tuition and fees, with remaining balances available for textbooks, approved tutoring, transportation, technology",
      "rationale": "Includes technology after tuition and fees, but omits department requirements and the restriction to the recipient's educational needs."
    },
    {
      "proposition_id": "P15",
      "status": "partial",
      "summary_quote": "Funds must first cover tuition and fees, with remaining balances available for textbooks, approved tutoring, transportation, technology, certain academic programs",
      "rationale": "Includes academic programs as a remaining-funds use, but omits summer and specialized afterschool scope, covered expenses, department requirements, and the childcare exclusion."
    },
    {
      "proposition_id": "P16",
      "status": "partial",
      "summary_quote": "Funds must first cover tuition and fees, with remaining balances available for textbooks, approved tutoring, transportation, technology, certain academic programs, approved postsecondary exams",
      "rationale": "Includes approved postsecondary examinations, but omits early postsecondary courses and industry credentials and does not distinguish opportunity examinations from required admissions examinations."
    },
    {
      "proposition_id": "P17",
      "status": "partial",
      "summary_quote": "Funds must first cover tuition and fees, with remaining balances available for textbooks, approved tutoring, transportation, technology, certain academic programs, approved postsecondary exams, and educational therapy.",
      "rationale": "Includes educational therapy after tuition and fees, but omits the requirement that therapists meet department requirements."
    },
    {
      "proposition_id": "P18",
      "status": "omitted",
      "summary_quote": "",
      "rationale": "Does not state that accounts remain open and available funds carry over between school years."
    },
    {
      "proposition_id": "P19",
      "status": "partial",
      "summary_quote": "Scholarship accounts close upon graduation, enrollment in a public school, completion of 13 school years, voluntary withdrawal, or disqualification.",
      "rationale": "Lists most closure events, but omits approved equivalency credentials, the earliest-event rule, disqualification for noncompliance, and return of remaining funds to the treasurer for future scholarships."
    },
    {
      "proposition_id": "P20",
      "status": "partial",
      "summary_quote": "Recipients in grades 3 through 11 must take an annual standardized achievement test.",
      "rationale": "Covers grade range and annual testing, but omits the nationally standardized, instructional-plan-aligned option and the alternative grade-specific Tennessee comprehensive assessment."
    },
    {
      "proposition_id": "P21",
      "status": "partial",
      "summary_quote": "Private schools that enroll recipients must provide these test results to parents and the office of research and education accountability.",
      "rationale": "Conveys schools' duty to provide results to parents, but not their duty to administer the required tests annually."
    },
    {
      "proposition_id": "P22",
      "status": "partial",
      "summary_quote": "Private schools that enroll recipients must provide these test results to parents and the office of research and education accountability.",
      "rationale": "Identifies the reporting schools and receiving office, but omits the annual June 30 deadline beginning in 2026 and the aggregated-data, prescribed-form, and demographic-analysis provisions."
    },
    {
      "proposition_id": "P23",
      "status": "omitted",
      "summary_quote": "",
      "rationale": "Does not mention the office's annual assessment-results report to the senate and house education committees."
    },
    {
      "proposition_id": "P24",
      "status": "partial",
      "summary_quote": "The bill specifies that participating private schools remain autonomous",
      "rationale": "Conveys autonomy but omits the independent declaration that participating schools are not state agents."
    },
    {
      "proposition_id": "P25",
      "status": "partial",
      "summary_quote": "The bill specifies that participating private schools remain autonomous and cannot be forced to change their policies or curriculum to accept recipients.",
      "rationale": "Conveys protection for school policies and curriculum, but omits the narrowly tailored enforcement limit on state and LEA regulatory authority and does not fully identify protected creeds and practices."
    },
    {
      "proposition_id": "P26",
      "status": "full",
      "summary_quote": "Students cannot receive these scholarships if they are already in the Tennessee education savings account pilot program or the individualized education account program",
      "rationale": "Conveys the prohibition on concurrent scholarship receipt and participation in either named program."
    },
    {
      "proposition_id": "P27",
      "status": "partial",
      "summary_quote": "nor do they retain the right to receive an individualized education program (IEP) from their local education agency (LEA).",
      "rationale": "Conveys loss of the resident-LEA IEP entitlement, but omits retained IDEA equitable-services rights through an individualized service plan."
    },
    {
      "proposition_id": "P28",
      "status": "omitted",
      "summary_quote": "",
      "rationale": "Does not mention the prohibition on direct payments to recipients or parents."
    },
    {
      "proposition_id": "P29",
      "status": "omitted",
      "summary_quote": "",
      "rationale": "Does not identify scholarships as a state or local public benefit."
    },
    {
      "proposition_id": "P30",
      "status": "omitted",
      "summary_quote": "",
      "rationale": "Does not discuss the exclusion of program funds from taxable income for recipients and parents."
    },
    {
      "proposition_id": "P31",
      "status": "omitted",
      "summary_quote": "",
      "rationale": "Does not mention denial for failure to establish lawful presence in the United States."
    },
    {
      "proposition_id": "P32",
      "status": "omitted",
      "summary_quote": "",
      "rationale": "Does not describe department rulemaking under the Uniform Administrative Procedures Act or an administrative appeal procedure for denied applications."
    },
    {
      "proposition_id": "P33",
      "status": "partial",
      "summary_quote": "Additionally, the bill would provide sole state-funded additional allocations to LEAs that experience disenrollment and a decrease in TISA funding.",
      "rationale": "Conveys additional funding when disenrollment and reduced TISA funding coincide, but omits the 2025-2026 start, restoration to the prior-year allocation, continuing-protection exception, and non-virtual membership definition."
    },
    {
      "proposition_id": "P34",
      "status": "partial",
      "summary_quote": "Additionally, the bill would provide sole state-funded additional allocations to LEAs that experience disenrollment and a decrease in TISA funding.",
      "rationale": "Conveys the general supplemental-funding protection, but omits the 2026-2027 start, prior-receipt condition, and preservation of the preceding year's allocation plus supplemental funds."
    },
    {
      "proposition_id": "P35",
      "status": "partial",
      "summary_quote": "Additionally, the bill would provide sole state-funded additional allocations to LEAs that experience disenrollment and a decrease in TISA funding.",
      "rationale": "Conveys sole state funding, but omits the prohibition on also receiving additional funds under subsections (b) or (c)."
    },
    {
      "proposition_id": "P36",
      "status": "partial",
      "summary_quote": "It also proposes a one-time $2,000 state-funded bonus for K-12 public school teachers employed during the 2024-2025 school year.",
      "rationale": "Covers amount, one-time nature, funding, and employment year, but omits the appropriation condition, department award duty, and statutory existing-educator definition."
    },
    {
      "proposition_id": "P37",
      "status": "omitted",
      "summary_quote": "",
      "rationale": "Does not state that bonuses are outside TISA and are not salary payments or supplements."
    },
    {
      "proposition_id": "P38",
      "status": "partial",
      "summary_quote": "Finally, the bill amends the distribution of privilege tax collected for the construction and maintenance of public school buildings",
      "rationale": "Conveys a privilege-tax distribution change for school buildings, but omits the 80% share, council transfer duty, treasurer-administered LEA account, and the statutory provision identifying the tax being amended."
    },
    {
      "proposition_id": "P39",
      "status": "partial",
      "summary_quote": "requiring the state treasurer to consider economic distress, natural disasters, and other demonstrated needs.",
      "rationale": "Conveys the treasurer's consideration duty, but omits designated distressed or at-risk county status, emergencies, significant damage to existing school facilities, and LEA identification of other needs."
    },
    {
      "proposition_id": "P40",
      "status": "omitted",
      "summary_quote": "",
      "rationale": "Does not mention severability or preservation of provisions and applications unaffected by invalidity."
    },
    {
      "proposition_id": "P41",
      "status": "full",
      "summary_quote": "Most provisions would take effect upon becoming law, except for the privilege tax changes, which would take effect July 1, 2025.",
      "rationale": "Conveys both effective dates and correctly identifies the privilege-tax amendment as the exception."
    }
  ]
}
